package com.ping.interest;
import java.util.*;
import com.ping.event.*;import com.ping.participant.*;import com.ping.entry.ParticipantEntryService;import com.ping.match.*;import com.ping.web.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:interest-categories;MODE=MySQL;DB_CLOSE_DELAY=-1") @ActiveProfiles("test")
class InterestCategoryTests {
 @Autowired InterestService interests;@Autowired InterestCatalogService catalog;@Autowired ParticipantService people;@Autowired EventService events;@Autowired ParticipantEntryService entry;@Autowired MatchingService matching;@Autowired MatchService matches;@Autowired JdbcTemplate sql;
 long event;
 @BeforeEach void setup(){sql.update("delete from feedback");sql.update("delete from match_reservations");sql.update("delete from ping_matches");sql.update("delete from participant_interests");sql.update("delete from participants");sql.update("delete from events");sql.update("update interest_categories set active=true");sql.update("update interests set category_id=2 where name='Tecnología'");EventForm f=new EventForm();f.setName("Categorías");event=events.create(f).getId();events.transition(event,EventStatus.OPEN);}
 long interest(String name){return interests.catalog().stream().filter(i->i.getName().equals(name)).findFirst().orElseThrow().getId();}
 long person(String alias){ParticipantForm f=new ParticipantForm();f.setAlias(alias);f.setEventId(event);f.setAvailable(true);return people.create(f).id();}
 void select(long person,Long... ids){var f=interests.selection(person);f.setInterestIds(List.of(ids));interests.save(person,f);}
 @Test void inactiveCategoryRetainsExistingChoicesButCannotBeAddedAgainAfterRemoval(){long a=person("Uno"),b=person("Dos"),music=interest("Música"),tech=interest("Tecnología");select(a,music);sql.update("update interest_categories set active=false where id=1");select(a,music,tech);assertThat(people.get(a).interests()).containsExactlyInAnyOrder("Música","Tecnología");assertThatThrownBy(()->select(b,music)).isInstanceOf(BusinessRuleException.class);assertThat(people.get(b).interests()).isEmpty();assertThat(interests.groups(List.of(music))).anySatisfy(g->{assertThat(g.name()).isEqualTo("Conservados");assertThat(g.choices()).anyMatch(c->c.id()==music&&!c.available());});select(a,tech);assertThatThrownBy(()->select(a,music,tech)).isInstanceOf(BusinessRuleException.class);assertThat(people.get(a).interests()).containsExactly("Tecnología");}
 @Test void unassignedInterestsRemainSelectableAndGrouped(){long tech=interest("Tecnología");sql.update("update interests set category_id=null where id=?",tech);assertThat(interests.groups(List.of())).anySatisfy(g->{assertThat(g.name()).isEqualTo("Otros intereses");assertThat(g.choices()).anyMatch(c->c.id()==tech&&c.available());});long a=person("Sin categoría");select(a,tech);assertThat(people.get(a).interests()).containsExactly("Tecnología");}
 @Test void inactiveChoiceInNewEntryRollsBackParticipantCreation(){long music=interest("Música");sql.update("update interest_categories set active=false where id=1");assertThatThrownBy(()->entry.create("Borrador",event,List.of(music))).isInstanceOf(BusinessRuleException.class);assertThat(sql.queryForObject("select count(*) from participants",Integer.class)).isZero();assertThat(entry.create("Entrada válida",event,List.of(interest("Tecnología")))).isPositive();}
 @Test void sharedCategoryDoesNotBecomeSharedInterest(){long a=person("Busca música"),b=person("Cine y mayor espera"),c=person("Música real");select(a,interest("Música"));select(b,interest("Cine"));select(c,interest("Música"));long match=matching.search(a);assertThat(matches.get(match,a).otherAlias()).isEqualTo("Música real");assertThat(matches.get(match,a).commonInterests()).isEqualTo("Música");}
}
